/* The tables of M41 · School website. */

/** One row per organisation. */
export const siteSettings = defineTable(
  'site_settings',
  { module: 'M41', scope: 'org' },
  {
    ...baseColumns,
    isPublished: boolean().notNull().default(false),
    customDomain: text(),
    domainStatus: enumText(siteSettingDomainStatuses).notNull().default('none'),
    /** the value the school puts in a DNS record to prove ownership */
    domainToken: text(),
    /** `en`, `ur` */
    languages: text()
      .array()
      .notNull()
      .default(sql`'{en}'::text[]`),
    defaultLanguage: enumText(locales).notNull().default('en'),
    /** `{ primary, accent, headerStyle: light \ | dark \ | brand }`; colours must pass the contrast check */
    theme: jsonb().notNull().default({}),
    tagline: text(),
    taglineUr: text(),
    /** phone, WhatsApp, email, address, map coordinates, office hours, per branch */
    contact: jsonb().notNull().default({}),
    /** Facebook, Instagram, YouTube, X links; `https` only */
    social: jsonb().notNull().default({}),
    seo: jsonb().notNull().default({}),
    /** which public features are on: admissions, jobs, events, transport, certificate check, fee payment, results notice */
    features: jsonb().notNull().default({}),
    analyticsId: text(),
    footerText: text(),
  },
  (t) => [
    check('site_settings_custom_domain_lower', sql`${t.customDomain} = lower(${t.customDomain})`),
    uniqueIndex('site_settings_custom_domain_uq')
      .on(t.customDomain)
      .where(sql`${t.deletedAt} is null and ${t.customDomain} is not null`),
    uniqueIndex('site_settings_org_uq').on(t.orgId).where(live(t)),
  ],
);

export const sitePages = defineTable(
  'site_pages',
  { module: 'M41', scope: 'org' },
  {
    ...baseColumns,
    /** lower case, hyphens; `home` is the front page */
    slug: text().notNull(),
    title: text().notNull(),
    titleUr: text(),
    /** an ordered list of blocks, each validated by its own schema */
    blocks: jsonb().notNull(),
    /** the Urdu version; falls back to English blocks with Urdu text where given */
    blocksUr: jsonb(),
    seoTitle: text(),
    seoDescription: text(),
    status: enumText(sitePageStatuses).notNull().default('draft'),
    /** what the public sees; set when published */
    publishedBlocks: jsonb(),
    publishedAt: timestamptz(),
    updatedBy: uuid().references((): AnyPgColumn => profiles.id),
  },
  (t) => [uniqueIndex('site_pages_slug_uq').on(t.orgId, t.slug).where(live(t))],
);

/** News and announcements. */
export const sitePosts = defineTable(
  'site_posts',
  { module: 'M41', scope: 'org' },
  {
    ...baseColumns,
    slug: text().notNull(),
    title: text().notNull(),
    titleUr: text(),
    excerpt: text(),
    /** rich text, sanitised */
    body: text().notNull(),
    bodyUr: text(),
    coverFileId: uuid().references((): AnyPgColumn => files.id),
    category: enumText(sitePostCategories).notNull().default('news'),
    branchId: uuid().references((): AnyPgColumn => branches.id),
    status: enumText(sitePostStatuses).notNull().default('draft'),
    publishAt: timestamptz(),
    publishedAt: timestamptz(),
    authorId: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
  },
  (t) => [
    uniqueIndex('site_posts_slug_uq').on(t.orgId, t.slug).where(live(t)),
    index('site_posts_status_published_at_idx').on(t.orgId, t.status, t.publishedAt),
  ],
);

/** Images for galleries and blocks. Stored in the one public bucket. */
export const siteMedia = defineTable(
  'site_media',
  { module: 'M41', scope: 'org' },
  {
    ...baseColumns,
    fileId: uuid()
      .references((): AnyPgColumn => files.id)
      .notNull(),
    /** a description for people who cannot see the image */
    alt: text().notNull(),
    altUr: text(),
    /** "Sports day 2026" */
    album: text(),
    caption: text(),
    sortOrder: integer().notNull().default(0),
    /** confirmed that the people shown may appear publicly */
    hasConsent: boolean().notNull().default(false),
  },
);

export const siteMenus = defineTable(
  'site_menus',
  { module: 'M41', scope: 'org' },
  {
    ...baseColumns,
    location: enumText(siteMenusLocations).notNull(),
    /** `{ label, labelUr?, kind: page \ | post_list \ | feature \ | link, target, children?: [] }[]`; two levels at most */
    items: jsonb().notNull(),
  },
  (t) => [uniqueIndex('site_menus_location_uq').on(t.orgId, t.location).where(live(t))],
);

/** What visitors send through the contact form. */
export const siteContactMessages = defineTable(
  'site_contact_messages',
  { module: 'M41', scope: 'org' },
  {
    ...baseColumns,
    name: text().notNull(),
    /** one of phone and email is required */
    phone: text(),
    email: text(),
    subject: text(),
    message: text().notNull(),
    branchId: uuid().references((): AnyPgColumn => branches.id),
    pageSlug: text(),
    status: enumText(siteContactMessageStatuses).notNull().default('new'),
    handledBy: uuid().references((): AnyPgColumn => profiles.id),
    handledNote: text(),
  },
  (t) => [check('site_contact_messages_message_maxlen', sql`char_length(${t.message}) <= 2000`)],
);
